import{c as t,Q as n,j as o,m as s}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/settings.md","filePath":"user/reference/settings.md"}'),r={name:"user/reference/settings.md"};function i(a,e,l,h,d,p){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators configuring Manager&#39;s global defaults.</p><p>Reference for every setting on the <strong>Settings</strong> page, what it controls, and the trade-offs for changing it.</p><blockquote><p><strong>Status:</strong> Stub — not yet written. This page should list every visible setting; it will be kept in sync with the Settings UI.</p></blockquote><h2 id="what-this-page-will-cover" tabindex="-1">What this page will cover <a class="header-anchor" href="#what-this-page-will-cover" aria-label="Permalink to &quot;What this page will cover&quot;">​</a></h2><ul><li>[ ] Where the <strong>Settings</strong> page is and how to open it</li><li>[ ] Each settings section (one subsection per section in the UI), in the order they appear: <ul><li><p>[ ] <strong>Custom fields</strong> (Global registry group) — extra fields recorded against every competitor, beyond the built-in ones. Shared across all events, so the same set is there for every event you run.</p><ul><li>Each field has a name of your choosing and holds either <strong>text</strong> or a <strong>number</strong>. The type decides how the value sorts in a column: a Number field sorts numerically, so 9 comes before 10 rather than after it. Values are always stored as text either way, and a value that can&#39;t be read as a number sorts last.</li><li>Use <strong>Move up</strong> / <strong>Move down</strong> to set the order fields appear in, everywhere they are shown.</li><li><strong>Renaming a field keeps the values competitors already hold.</strong> Removing one hides it without deleting those values, so adding the field back <em>under the same name</em> brings them with it — under different wording it is a new, empty field.</li><li>Fields appear on the <strong>Custom fields</strong> tab of a competitor, on a <strong>Competitor registry</strong> entry, and as optional columns in the Competitors list and the Competitor registry table. In the Competitors list they are off by default (turn them on from the Columns menu); in the registry table they are shown by default.</li><li>Values recorded on a <strong>Competitor registry</strong> entry follow that person into every event they enter: they are copied onto the competitor when you import entries from Eventor or from an IOF XML entry list, and when you pick the person from the registry in the Edit Competitor dialog. A value already on the competitor always wins, so re-importing an entry list never overwrites a correction you made in the event — it only fills in fields that are still blank.</li><li>For an IOF XML file, the link relies on the file carrying the athlete&#39;s <strong>IOF ID</strong>. Entry lists exported by Eventor normally do; a file without it cannot be tied to a registry person, so those competitors arrive with the fields blank. Card number and name are deliberately not used for the match, because hire cards change hands.</li><li>Custom fields are <strong>not included in exports</strong> — not in IOF XML, results, or splits printouts. They are for your own records.</li><li>If you have enabled <a href="./ai-assistants-mcp">AI assistants (MCP)</a>, custom fields are among the competitor details an assistant can read. Bear that in mind for anything sensitive, such as a phone number.</li></ul></li><li><p>[ ] <strong>Prime Connection</strong> — serial connection to the meshO Prime field unit (COM port, baud rate, retry intervals, &quot;use Prime for radio punches&quot; default)</p></li><li><p>[ ] <strong>Event Defaults</strong> — values applied when creating new events (start/finish/check unit codes, default event type, competition level, discipline, punching-start override default)</p></li><li><p>[ ] <strong>Replay Mode</strong> — replay speed for reviewing past events</p></li><li><p>[ ] <strong>Logging</strong> — log level (Verbose, Debug, Info, Warning, Error)</p></li><li><p>[ ] <strong>Eventor</strong> — Host Name, API Key, Organisation ID for the Eventor connection</p></li><li><p>[ ] <strong>Screen Defaults</strong> — defaults for new Leaderboard screens (club display, club icon, auto-scroll, max radios per class, time display options, single-line team members, max places per class)</p></li><li><p>[ ] <strong>Radio Punch Forwarding</strong> — TCP forwarding of radio punches to external systems (host, port, SIRAP or OE12 protocol, client name)</p></li><li><p>[ ] <strong>Radio Punch Listening</strong> — accept incoming SIRAP punches over TCP (listen port)</p></li><li><p>[ ] <strong>Splits printer</strong> — two separate things on one page. <strong>Printer connection</strong> is the printer — or printers — the <em>server</em> prints on: the <strong>Enable server splits printer</strong> switch, connection type, paper width, the list of named network printers, and a test print for each. <strong>Splits printer defaults</strong> is what a printout contains — auto-print on download, whether a mis-punch printout is held while you correct the class and for how long, logo, top 3 places, splits language, and the QR code (its own switch, plus the address, heading and caption) — for every event on the server, and each event can override most of them in <strong>Event details → Splits print</strong>. The defaults stay available with the connection switched off, because they are also what a download station&#39;s own printer prints from — auto-print on download included: it says whether a download prints without being asked, and both the server&#39;s printer and a station printing on its own obey it. There are two connection types, and the distinction matters on multi-computer setups:</p><ul><li><strong>Network printer (TCP)</strong> — the server opens a TCP connection to a host and port (default <code>localhost:9100</code>) and sends ESC/POS bytes. Use this for any printer reached over the network, including a printer physically attached to a <em>different</em> computer (e.g. a download station), provided that computer runs something that accepts raw TCP on the configured port and passes it to the printer. This is a <strong>list</strong>: add as many printers as you have, give each a name for where it stands (<em>Left lane</em>, <em>Women&#39;s Elite</em>, <em>Public</em>), and mark one as the <strong>Default</strong>. Each row has its own test button. The default is where a slip goes when nothing names a printer; each download station can name one instead, in <strong>Event details → Splits print</strong>.</li><li><strong>Printer attached to this computer (Windows only)</strong> — drives a printer installed on the Windows machine <strong>running the server</strong>, via the print spooler/driver. &quot;This computer&quot; means the server computer, <em>not</em> the browser/download computer you may be reading these settings on. A USB printer plugged into a download station is <strong>not</strong> reachable this way — use the Network option for that. Choose the print language (Epson ESC/POS or the Windows driver) and select the printer from those installed on the server.</li></ul><p>The connection <em>type</em> is a single, server-wide setting: the server either prints over the network or on a printer attached to itself. Which <strong>network printer</strong> a slip comes out on is not — each download station picks from the named list in <strong>Event details → Splits print</strong>, and stations that pick nothing use the default.</p><ul><li><strong>Printing to a USB printer on a download station.</strong> If you want each download laptop to print to <em>its own</em> USB thermal printer — rather than to one of the server&#39;s network printers — use the per-station option instead: on that laptop, open the event&#39;s <strong>Event details → Splits print</strong> tab and turn on <strong>Print splits on this station</strong>, then pick the printer. This is a per-station setting saved on that computer (not part of the event), so it takes effect immediately and applies to every event you open there. It prints in the browser via WebUSB, so — like card download — it needs a secure connection on any computer other than the server (see <a href="./https-and-certificates">HTTPS and certificates</a>). The browser must be Chrome or Edge: WebUSB is a different API to the Web Serial one card download uses, and Firefox has Web Serial but not WebUSB. A station set up this way prints its own downloads locally and the server printer is skipped for them, so there&#39;s no double printing. Full guide: <a href="./../running-the-event/splits-printing">Printing splits</a></li></ul></li><li><p>[ ] <strong>Access Protection</strong> — optional shared-PIN protection for manager screens</p></li><li><p>[ ] <strong>Auto Backup</strong> — enable, and the frequency in minutes (5, 10, 15, 30, 60) — defaults applied to new events; each event can override</p></li><li><p>[ ] <strong>Auto Update</strong> — automatically download and install new releases</p></li><li><p>[ ] <strong>AI assistants</strong> — lets an AI assistant read the live event over MCP, and optionally make changes. Off by default; both switches need a server restart. Full guide: <a href="./ai-assistants-mcp">AI assistants (MCP)</a></p></li><li><p>[ ] <strong>Server</strong> — this computer&#39;s name/LAN IP, the HTTP port the server listens on (default 5154), LAN access toggle, shareable access links, and optional <strong>HTTPS</strong> for download/backup stations on other computers (see <a href="./https-and-certificates">HTTPS and certificates</a>)</p></li></ul></li><li>[ ] The <code>settings.yaml</code> file — where it is, what&#39;s safe to edit by hand, and what isn&#39;t</li><li>[ ] Restoring defaults</li><li>[ ] Migrating settings between machines</li><li>[ ] Application folders — where Manager stores events, downloads, backups, and logs on disk</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../download-and-install/">Installing meshO Manager</a></li><li><a href="./ai-assistants-mcp">AI assistants (MCP)</a></li><li><a href="./https-and-certificates">HTTPS and certificates</a></li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a></li></ul>',8)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
